/**
* Maps legacy/summary 5-defect IDs in INSCO Academy's Defect Diagnostic tab (`EDUCATIONAL_DEFECTS`)
* to the 16-defect engineering catalog so both simulators share identical code tolerance calculations.
*/
function mapEducationalDefectToCatalogId(eduDefectId) {
	switch (eduDefectId) {
		case "crack": return "root_crack";
		case "lack_of_fusion": return "lack_of_fusion";
		case "slag": return "slag_inclusion";
		case "porosity": return "porosity_cluster";
		case "undercut": return "toe_undercut";
		default: return "root_crack";
	}
}
