		canvasWidth: width,
		canvasHeight: height,
		plateThicknessMm,
		probeIndexOffsetMm,
		minAngleDeg,
		maxAngleDeg,
		selectedAngleDeg,
		showSkipMirror,
		bevelConfig,
		flaw
